import { test } from "node:test";
import assert from "node:assert/strict";
import { backoff } from "../src/retry.mjs";

test("a failed call backs off 1, 2, 4 minutes, then stops", () => {
  assert.deepEqual([0, 1, 2, 3, 4].map((n) => backoff(n, 6)), [60, 120, 240, 480, 960]);
});

test("the sixth failure is not retried", () => {
  assert.equal(backoff(6, 6), null);
});
